    quantity: Number(r.quantity) || 0,
    unit_price: Number(r.unit_price) || 0,
    effective_unit_price: paidPerUnit,
    refund_amount: Number(r.refund_amount) || 0,
    requested_refund: r.requested_refund != null ? Number(r.requested_refund) : void 0,
    approved_quantity: r.approved_quantity ?? void 0,
    restocked: r.restocked ?? void 0,
    reason: r.reason,
    action: r.action,
    status: r.status,
    user_id: r.user_id,
    user_name: r.user_name || "Staff",
    device_id: r.device_id,
    reviewed_by: r.reviewed_by || void 0,
    reviewed_by_name: r.reviewed_by_name || void 0,
    reviewed_at: r.reviewed_at ? new Date(r.reviewed_at).toISOString() : void 0,
    review_notes: r.review_notes || void 0,
    refund_method: r.refund_method || void 0,
    refund_shift_id: r.refund_shift_id || void 0,
    sale_date: r.sale_date || "",
    sale_time: r.sale_time || "",
